B.bXI=new A.hw("1. OBJETIVO",null)
B.bX3=new A.kE("Esta Politica de Privacidade explica como a DeliGo recolhe, utiliza, partilha e protege dados pessoais de clientes, estafetas, restaurantes e administradores no ambito da utilizacao da aplicacao e servicos associados.",null)
B.bXQ=new A.hw("2. RESPONSAVEL PELOS DADOS",null)
B.bXd=new A.kE("A Deligo Triunfal, LDA atua como responsavel pelo tratamento dos dados pessoais recolhidos atraves da plataforma DeliGo.",null)
B.bXS=new A.hw("3. DADOS QUE PODEMOS RECOLHER",null)
B.bYp=new A.yc("3.1 Dados de conta",null)
B.aKF=s(["Nome e dados de perfil","Numero de telefone","Email, quando fornecido","Foto de perfil, quando enviada"],t.s)
B.bVE=new A.kA(B.aKF,null)
B.bYz=new A.yc("3.2 Dados de verificacao e compliance",null)
B.aOS=s(["Documentos de identificacao e respetiva informacao","Selfie ou foto para verificacao","Dados necessarios para prevencao de fraude e cumprimento legal"],t.s)
B.bVg=new A.kA(B.aOS,null)
B.bYr=new A.yc("3.3 Dados de pedidos e pagamentos",null)
B.aGA=s(["Historico de pedidos","Endereco de entrega e coordenadas relacionadas","Valores, taxas e estado das transacoes","Registos de wallet, depositos e levantamentos"],t.s)
B.bVk=new A.kA(B.aGA,null)
B.bYs=new A.yc("3.4 Dados de localizacao",null)
B.aEq=s(["Localizacao aproximada e precisa para mapas e cobertura","Rastreamento do pedido e do estafeta","Calculo de rotas e tempos estimados"],t.s)
B.bVc=new A.kA(B.aEq,null)
B.bYn=new A.yc("3.5 Comunicacoes e dados tecnicos",null)
B.aHS=s(["Mensagens de chat e suporte","Notificacoes push e preferencias","Identificadores da aplicacao, analytics, crash logs e diagnosticos"],t.s)
B.bVe=new A.kA(B.aHS,null)
B.bYe=new A.hw("4. COMO UTILIZAMOS OS DADOS",null)
B.aOd=s(["Criar e gerir contas","Processar pedidos, entregas e levantamentos","Processar pagamentos e reconciliacoes","Ativar chat, notificacoes e suporte","Prevenir fraude e reforcar a seguranca","Cumprir obrigacoes legais, fiscais e regulatorias","Melhorar o desempenho e a confiabilidade da plataforma"],t.s)
B.bVo=new A.kA(B.aOd,null)
B.bXL=new A.hw("5. PARTILHA DE DADOS",null)
B.bX7=new A.kE("Clientes, restaurantes e estafetas podem ver os dados minimos necessarios para executar um pedido. Tambem podemos partilhar dados com prestadores de pagamentos, infraestrutura, analytics, suporte tecnico e autoridades competentes quando exigido por lei.",null)
B.bXJ=new A.hw("6. RETENCAO",null)
B.bXk=new A.kE("Mantemos os dados pelo tempo necessario para prestar o servico, cumprir requisitos legais, prevenir fraude, resolver disputas e manter a integridade operacional e financeira da plataforma.",null)
B.bYc=new A.hw("7. SEGURANCA",null)
B.bX_=new A.kE("Adotamos medidas tecnicas e organizacionais para proteger os dados, incluindo controlos de acesso, autenticacao, validacoes do lado do servidor e monitorizacao. Nenhum sistema e 100% seguro, mas trabalhamos continuamente para reduzir riscos.",null)
B.bY8=new A.hw("8. DIREITOS DO UTILIZADOR",null)
B.aFh=s(["Solicitar acesso aos seus dados","Solicitar correcao de dados","Solicitar eliminacao ou encerramento de conta, quando possivel","Retirar consentimentos, quando o tratamento depender de consentimento"],t.s)
B.bVG=new A.kA(B.aFh,null)
B.bXi=new A.kE("Os pedidos de eliminacao de conta podem ser feitos diretamente na aplicacao DeliGo, na secao Configuracoes. Pedidos com saldo, pedidos ativos, disputas ou obrigacoes legais podem passar por revisao manual antes da eliminacao definitiva.",null)
B.bY1=new A.hw("9. TECNOLOGIAS SEMELHANTES A COOKIES",null)
B.bWZ=new A.kE("A aplicacao pode utilizar identificadores e tecnologias semelhantes para manter sessao, prevenir fraude, suportar analytics e melhorar o servico.",null)
B.bYd=new A.hw("10. ALTERACOES",null)
B.bX1=new A.kE("Podemos atualizar esta politica periodicamente. A versao mais recente deve estar disponivel nos canais oficiais da DeliGo.",null)
B.a90=new A.hw("11. CONTACTO",null)
B.a8s=new A.ak0(null)
